    clusterId: "psicopatologia",
    conceptoA: { escuela: "h6d", nombre: "Modos de ser inauténticos" },
    conceptoB: { escuela: "p1", nombre: "Mecanismos de defensa" },
    relacion: "solapamiento parcial",
